/**
 * The read-only lock a workspace falls into while its subscription is not in good standing.
 *
 * Pure on purpose: no database access, so `lib/errors.ts` can translate the error without
 * importing the server layer. `billing-service` loads the subscription and asks this module.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Raised by a write path when the workspace is locked. Nothing has been written when it is thrown. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only while its subscription is ${reason}`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The lock rule. A missing subscription or an `active` one is writable. A `trialing` workspace
 * locks once its period end is reached, and a `canceled` one locks once its cancellation date
 * is reached (immediately when no date was recorded).
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  const at = now.getTime();

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return at >= Date.parse(subscription.currentPeriodEnd) ? "trial_ended" : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return at >= Date.parse(subscription.cancelAt) ? "canceled" : null;
